    ("promptvars expand", "`shopt -s promptvars` (default on) expands `$(...)` in PS1 for git branches/load; disable for literal prompts or untrusted PS1 strings."),
    ("restricted_shell", "`bash -r`/`rbash` jails PATH, redirections and `cd` — chroot-lite for sftp-style accounts; combine with owned-writable-nothing homes."),
    ("shift_verbose", "`shopt -s shift_verbose` errors when `shift` exceeds `$#` — argument parsers catch missing values instead of silently emptying."),
    ("sourcepath lookup", "`shopt -u sourcepath` stops `source file` searching PATH (current dir only) — scripts stop accidentally sourcing roaming namesakes."),
    ("xpg_echo portability", "`shopt -s xpg_echo` makes `echo` expand backslashes portably; better: use `printf` and never depend on echo flavors again."),
    ("expand_aliases scripts", "`shopt -s expand_aliases` (off in scripts by default) enables aliases non-interactively — functions are still the sane choice with arguments."),
    ("login_shell detect", "`shopt -q login_shell && echo login` branches rc logic (paths vs aliases); `/etc/profile` vs `~/.bashrc` split lives here."),
    ("posix mode", "`set -o posix`/`bash --posix` disables bashisms for `/bin/sh` testing — scripts meant portable get verified, not assumed."),
    ("braceexpand toggle", "`set +B` disables brace expansion for literal `{a,b}` data; re-enable after — parsers handling brace-heavy formats need this."),
    ("emacs vi mode", "`set -o vi` gives modal command-line editing (Esc, `/` search history); `set -o emacs` restores default — muscle memory per admin."),
    ("physical cd", "`set -o physical` (`cd -P`) resolves symlinks physically so `..` climbs real parents — deploy paths with linked releases stop surprising."),
    ("allexport vars", "`set -a` auto-exports every assignment until `set +a` — `.env` sourcing pattern (`set -a; source .env; set +a`) in one idiom."),
    ("notify jobs", "`set -b` reports background terminations immediately instead of at next prompt — long parallel batches narrate themselves."),
    ("errtrace functrace", "`set -E` routes ERR traps through functions/subshells; `-T` does it for DEBUG/RETURN — library-grade error reporting needs both."),
    ("verbose trace", "`set -v` echoes raw input lines, `-x` echoes expansions — `-v` shows what you wrote, `-x` what runs; combine for script autopsies."),
    ("noclobber safe", "`set -o noclobber` blocks `>` overwrites (use `>|` to force) — production logs and configs survive typo redirects."),
    ("noglob paths", "`set -f` disables globbing for literal `*`/`?` data (URLs, regex args); restore with `set +f` — curl patterns stop exploding."),
    ("noexec dryrun", "`bash -n script.sh` syntax-checks without executing — CI gates every shell change; `set -o noexec` mid-script freezes the rest as documentation."),
    ("onecmd flag", "`bash -c 'cmd'` runs one string and exits — `-s` reads stdin instead; scripts via SSH live here (`ssh host bash -s < fix.sh`)."),
    ("lastpipe variable", "`shopt -s lastpipe` runs the pipeline's last command in the current shell (non-interactive) — `cmd | read x` finally keeps `$x`."),
    ("inherit_errexit subshell", "`shopt -s inherit_errexit` propagates `set -e` into `$(...)` and subshells — command substitutions stop swallowing failures silently."),
    ("localvar_inherit", "`shopt -s localvar_inherit` passes function locals into nested calls — controlled dynamic scope without globals leaking everywhere."),
    ("assoc_expand_once", "`shopt -s assoc_expand_once` expands `assoc[$key]` subscripts once — keys with `$` or spaces stop double-expanding into chaos."),
    ("globasciiranges", "`shopt -s globasciiranges` forces `[a-z]` to C-locale byte ranges — UTF-8 locales otherwise smuggle accented letters into globs."),
    ("direxpand paths", "`shopt -s direxpand` expands `$vars` and `~` during TAB completion — long paths complete through variables, not just literals."),
    ("autocd dirs", "`shopt -s autocd` turns bare directory names into `cd` — interactive speed for navigators, never in scripts (spooky action)."),
    ("checkhash path", "`shopt -s checkhash` re-searches PATH when cached binaries vanish (reinstalls mid-session) — `hash -r` does it manually on demand."),
    ("dotglob hidden", "`shopt -s dotglob` includes dotfiles in `*` — backups and configs (`~/.ssh/*`) stop being invisibly skipped by globs."),
    ("extquote strings", "`shopt -s extquote` (default on) enables `$'..'` locale expansions inside `${var@Q}`-style contexts — leave it on unless debugging quoting."),
    ("checkwinsize resize", "`shopt -s checkwinsize` refreshes LINES/COLUMNS after every command — resized terminals reflow prompts instead of wrapping garbage."),
    ("cmdhist multiline", "`shopt -s cmdhist` stores multiline commands as one history entry (with `lithist` keeping real newlines) — recall whole functions, not fragments."),
    ("histappend share", "`shopt -s histappend` appends (never clobbers) history across concurrent shells; `PROMPT_COMMAND='history -a'` shares live between terminals."),
    ("DEBUG trap", "`trap 'echo \"+ $BASH_COMMAND\"' DEBUG` runs before every command — custom tracers with context that `set -x` cannot carry."),
    ("RETURN trap", "`trap '...' RETURN` fires on function/sourced-script return — paired with DEBUG for call-graph logging in tricky libraries."),
    ("ERR trap scope", "ERR traps need `set -E` to fire inside functions; report `$?`, `$LINENO`, `${FUNCNAME[0]}` then re-raise — silent traps hide the failures they caught."),
    ("PS4 custom", "`export PS4='+ ${BASH_SOURCE}:${LINENO}:${FUNCNAME[0]}: '` prefixes every `set -x` line with location — traces become navigable instantly."),
    ("BASH_XTRACEFD log", "`exec 5> trace.log; export BASH_XTRACEFD=5` routes `set -x` off stderr — program output and trace separate cleanly for CI artifacts."),
    ("coproc two-way", "`coproc BC { bc -l; }` opens two-way pipes (`${COPROC[0]/[1]}`); `echo '2^10' >&${COPROC[1]}` then `read -u ${COPROC[0]}` — interactive tools scripted."),
    ("mapfile callback", "`mapfile -t -c1 -C 'echo -n .' < big` runs a callback each chunk — progress dots for giant loads without extra loops."),
    ("read readline edit", "`read -e -i 'default' -p 'Name: ' v` enables readline editing with prefilled text — polished prompts with history and completion free."),
    ("bind shortcut", "`bind -x '\"\\C-l\":clear-screen'` binds keys to shell commands — personal accelerators; list with `bind -P`, persist in `~/.inputrc`."),
    ("complete custom", "`complete -F _deploy deploy` wires a function emitting `COMPREPLY` candidates; `-C 'cmd'` delegates to external completers — first-class CLI UX."),
    ("compgen list", "`compgen -W 'start stop' -- \"$cur\"` filters wordlists to current prefix — the engine inside every custom completion function."),
    ("bash version check", "`(( BASH_VERSINFO[0] >= 5 )) || exit 1` gates on major version; `${BASH_VERSION}` for logs — `assoc -A`/`wait -n` need 4+/5.1+."),
    ("shellcheck lint", "`shellcheck -S warning script.sh` lints quoting/expansions/portability with wiki-linked codes; gate CI on zero findings — the single highest-ROI shell habit."),
    ("shfmt format", "`shfmt -w -i 2 script.sh` normalizes style project-wide; `-d` diffs first — formatted diffs review logic, not whitespace."),
    ("bats testing", "`@test 'creates dir' { run ./setup.sh; [ $status -eq 0 ]; }` tests shell in TAP; `setup/teardown` isolate — shell finally unit-testable in CI."),
    ("rg ripgrep", "`rg -n --hidden -g '!lock' 'TODO'` respects .gitignore and skips binaries — grep-compatible flags, order-of-magnitude faster trees."),
    ("fd find", "`fd -e log -x rm` finds by extension and executes per hit; `-d2` depth-caps — humane defaults over find's flag soup."),
    ("bat pager", "`bat -n --style=plain f.sh` syntax-highlights with line numbers; `BAT_THEME` per terminal — `cat` for machines, `bat` for eyes."),
    ("htop vs top", "`htop` adds mouse, trees, per-CPU bars and kill-by-F9 over top; `atop` keeps history — interactive triage ladder: uptime, htop, logs."),
    ("ncdu disk", "`ncdu /` navigates disk usage interactively and deletes in place (`d`) — `du|sort` pipelines for scripts, ncdu for humans."),
    ("fzf history", "`history | fzf` fuzzy-finds past commands (`Ctrl-R` with fzf bindings replaces it live) — recall beats retyping for long one-liners."),
    ("entr rerun", "`ls *.sh | entr -r ./test.sh` reruns on save — tight feedback without watchers/IDEs; `-c` clears between runs."),
    ("hyperfine bench", "`hyperfine 'grep x f' 'rg x f'` benchmarks with warmup and statistics — claims about faster commands need numbers, not feelings."),
    ("jq walk reduce", "`jq '[.. | numbers] | add'` walks trees summing all numbers; `reduce .[] as $x (0; .+$x)` folds — JSON analytics without Python."),
    ("yq yaml", "`yq '.svc.port' app.yaml` queries YAML like jq; `-i` edits in place — config surgery without Python dependencies."),
    ("openssl s_client", "`openssl s_client -connect host:443 -servername host </dev/null | openssl x509 -noout -dates` checks live cert expiry — monitoring TLS without browsers."),
    ("openssl selfsign", "`openssl req -x509 -newkey rsa:2048 -keyout k.pem -out c.pem -days 365 -nodes -subj '/CN=dev'` mints dev certs non-interactively — local HTTPS in one line."),
    ("gpg encrypt sign", "`gpg --encrypt -r ops@x backup.tgz` encrypts to recipients; `--detach-sign` proves authorship — keys in hardware/YubiKey for production."),
    ("age secrets", "`age -r age1... -o s.age secret` encrypts simply (no keyring); `-d -i key.txt` decrypts — modern replacement for ad-hoc GPG file encryption."),
    ("tmux send-keys", "`tmux send-keys -t deploy 'make release' Enter` drives panes scriptably; `new-window -n` layouts as code — scripted demo/ops consoles."),
    ("tmux synchronize", "`setw synchronize-panes on` broadcasts keystrokes to all panes — rolling restarts across N hosts watched live, then off again."),
    ("screen detach", "`screen -S job` persists; `Ctrl-A d` detaches, `-r` resumes — tmux's ancestor, still everywhere minimal installs lack tmux."),
    ("systemd mask", "`systemctl mask nginx` symlinks to /dev/null making starts impossible (stronger than disable); `unmask` reverses — compromised units neutralized fast."),
    ("systemd cat edit", "`systemctl cat app` shows merged unit+drop-ins; `systemctl edit app` creates override snippets safely — never edit vendor units directly."),
    ("systemd timer", "A `.timer` (`OnCalendar=daily`, `Persistent=true`) plus matching `.service` replaces cron with logging/dependencies/jitter — `list-timers` audits all schedules in one view."),
    ("lvm extend", "`lvextend -r -L +10G vg/lv` grows volume and filesystem online (`-r` handles ext4/xfs); `pvs/vgs/lvs` audit free space first — no downtime resizes."),
    ("tcpdump filter", "`tcpdump -i any -n port 443 -c 100 -w cap.pcap` captures precisely; `-A`/`-X` reads payloads live — reproduce first, theorize after."),
    ("strace syscall", "`strace -f -e trace=file -p PID` reveals every file access of a confused process; `-c` summarizes where time burns — behavior over source reading."),
    ("ss advanced", "`ss -s` summarizes socket stats; `-o state established '( dport = :443 )'` filters precisely — netstat is deprecated, ss scripts everything."),
    ("nmcli wifi", "`nmcli d wifi list` scans; `nmcli d wifi connect SSID password X` joins — scripted networking without editing wpa_supplicant by hand."),
    ("curl retry backoff", "`curl --retry 5 --retry-delay 2 --retry-all-errors` survives flaky endpoints; `--max-time` caps total — batch downloads stop dying on blips."),
    ("wget spider check", "`wget --spider -r -nd -nv site/ 2>&1 | grep -i broken` link-checks without downloading — dead-link audits for docs sites."),
    ("git archive deploy", "`git archive HEAD | tar -x -C /srv/app` deploys exact trees without `.git` weight; `--prefix` versions contents — clean releases from any ref."),
    ("pip download wheels", "`pip download -d ./wheels -r req.txt` vendors wheels for offline installs; `--no-deps` trims to direct needs — air-gapped deploys planned, not improvised."),
    ("python http server", "`python3 -m http.server 8000 -d ./pub` serves static instantly for LAN tests; `--bind 127.0.0.1` keeps it local — never production, always handy."),
