    ("\\warn notice", "`\\warn` writes to stderr without aborting scripts — progress markers that survive output redirects."),
    ("\\gdesc describe", "`\\gdesc` describes the would-be result columns without running the query — cheap shape checks."),
    ("\\gx expanded auto", "`\\gx` auto-switches expanded/plain per width — readable psql output on narrow and wide terminals alike."),
    ("\\watch count", "`\\watch 5 -c 3` repeats thrice (bounded watches for scripts); plain `\\watch` loops until Ctrl-C."),
    ("\\copy program", "`\\copy ... FROM PROGRAM 'cmd'` streams command output directly into tables — ETL without temp files."),
    ("\\set AUTOCOMMIT", "`\\set AUTOCOMMIT off` batches interactive work into explicit transactions; scripts should manage COMMIT explicitly."),
    ("\\pset footer", "`\\pset footer off` hides row counts for clean script output; `aligned`/`unaligned` toggle human vs machine formats."),
    ("\\pset null string", "Distinguish NULL (`[null]`) from empty strings visually — misread nulls corrupt ad-hoc analysis silently."),
    ("\\echo queries", "`\\echo :VERSION` prints psql/meta variables for script headers; `\\qecho` stays silent in logs."),
